-- C rollback: 보존 데이터가 있으면 권한 경계를 되돌리지 않는다. B/A는 그대로 유지한다.
begin;
do $$ begin if exists(select 1 from public.profile_employment_history) or exists(select 1 from public.profiles where employment_status<>'재직' or account_access_status<>'활성' or account_disabled_at is not null) then raise exception 'employment phase C rollback blocked: preserved data exists';end if;end $$;
revoke execute on function public.approve_employee_profile(uuid),public.revoke_employee_profile_approval(uuid),public.update_employee_profile_field(uuid,text,text) from authenticated;drop function if exists public.update_employee_profile_field(uuid,text,text);drop function if exists public.revoke_employee_profile_approval(uuid);drop function if exists public.approve_employee_profile(uuid);drop function if exists public.assert_employee_approver(uuid);grant update,delete on public.profiles to authenticated;create policy profiles_update_owner on public.profiles for update to authenticated using(public.my_role()='owner') with check(public.my_role()='owner');create policy profiles_delete_owner on public.profiles for delete to authenticated using(public.my_role()='owner');commit;
